def decide(recipient_reputation, round_num, my_history):
    # Initial cooperation phase: cooperate for first 10 rounds to build reputation
    if len(my_history) < 10:
        return True

    # Base threshold: starts at 0.0 and increases to 0.6 over 20 rounds
    progress = min(round_num / 20.0, 1.0)
    base_threshold = 0.0 + 0.6 * progress

    # Recent own cooperation ratio (last 10 rounds)
    recent_window = my_history[-10:] if len(my_history) >= 10 else my_history
    if recent_window:
        coop_count = sum(1 for a in recent_window if a == 'cooperate')
        total = len(recent_window)
        coop_ratio = coop_count / total
    else:
        coop_ratio = 0.5

    # Adjust threshold based on recent behavior: if very cooperative, lower threshold (more trust)
    if coop_ratio > 0.7:
        threshold = base_threshold - 0.2
    elif coop_ratio < 0.3:
        threshold = base_threshold + 0.2
    else:
        threshold = base_threshold

    # Additional forgiveness if overall cooperation is low (avoid defection spiral)
    total_coop = sum(1 for a in my_history if a == 'cooperate')
    total_rounds = len(my_history)
    overall_coop_ratio = total_coop / total_rounds if total_rounds else 0.5
    if overall_coop_ratio < 0.4 and round_num > 8:
        threshold -= 0.25

    # Encourage cooperation later in the game if historically cooperative
    if round_num > 30 and overall_coop_ratio > 0.6:
        threshold -= 0.15

    # If recipient has a very bad reputation, be slightly more forgiving (to break defection cycles)
    if recipient_reputation < -0.5:
        threshold -= 0.15

    # Reciprocate good reputations even more readily
    if recipient_reputation > 0.5:
        threshold -= 0.2

    return recipient_reputation >= threshold

